import React, { useState, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { updateInstructorsAsync } from '../../../store/contentSlice';
import { supabaseService } from '../../../services/supabaseService';
import Button from '../../../components/ui/Button';
import Icon from '../../../components/AppIcon';
import Modal from '../../../components/ui/Modal';
import { useToast } from '../../../contexts/ToastContext';
import ConfirmationModal from '../../../components/ui/ConfirmationModal';

const InstructorManagement = () => {
    const dispatch = useDispatch();
    const { addToast } = useToast();
    // Assuming instructors will be stored in content.instructors
    const instructors = useSelector((state) => state.content.instructors) || [];
    const [promoCodes, setPromoCodes] = useState([]);
    const [togglingPromo, setTogglingPromo] = useState(null);

    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingInstructor, setEditingInstructor] = useState(null);
    const [formData, setFormData] = useState({
        id: '',
        name: '',
        role: '',
        bio: '',
        avatar: '',
        socials: { linkedin: '', twitter: '' }
    });
    const [deleteId, setDeleteId] = useState(null);
    const [isDeleting, setIsDeleting] = useState(false);
    const [isUploading, setIsUploading] = useState(false);

    useEffect(() => {
        loadPromoCodes();
    }, []);

    const loadPromoCodes = async () => {
        try {
            const codes = await supabaseService.getAllInstructorPromoCodes();
            setPromoCodes(codes);
        } catch (err) {
            console.error('Failed to load promo codes:', err);
        }
    };

    const handleTogglePromo = async (promoId, currentActive) => {
        setTogglingPromo(promoId);
        try {
            await supabaseService.toggleInstructorPromoCode(promoId, !currentActive);
            setPromoCodes(prev => prev.map(p => p.id === promoId ? { ...p, is_active: !currentActive } : p));
            addToast(`Promo code ${!currentActive ? 'enabled' : 'disabled'}`, 'success');
        } catch (err) {
            console.error('Failed to toggle promo code:', err);
            addToast('Failed to toggle promo code', 'error');
        } finally {
            setTogglingPromo(null);
        }
    };

    const getPromoForInstructor = (instructorId) => {
        return promoCodes.find(p => p.instructor_id === instructorId);
    };

    const handleImageUpload = async (e) => {
        const file = e.target.files[0];
        if (!file) return;

        setIsUploading(true);
        try {
            const url = await supabaseService.uploadImage(file);
            setFormData(prev => ({ ...prev, avatar: url }));
            addToast('Image uploaded successfully', 'success');
        } catch (error) {
            console.error('Failed to upload image:', error);
            addToast('Failed to upload image', 'error');
        } finally {
            setIsUploading(false);
        }
    };

    const handleOpenModal = (instructor = null) => {
        if (instructor) {
            setEditingInstructor(instructor);
            setFormData(instructor);
        } else {
            setEditingInstructor(null);
            setFormData({
                id: `instr-${Date.now()}`,
                name: '',
                role: 'Senior Instructor',
                bio: '',
                avatar: 'https://i.pravatar.cc/150?u=' + Date.now(),
                socials: { linkedin: '', twitter: '' }
            });
        }
        setIsModalOpen(true);
    };

    const handleDeleteClick = (id) => {
        setDeleteId(id);
    };

    const performDelete = async () => {
        if (!deleteId) return;
        setIsDeleting(true);
        try {
            const updatedInstructors = instructors.filter(i => i.id !== deleteId);
            // Dispatch update action (we will create this thunk next)
            // Using a generic content update pattern for now
            await dispatch(updateInstructorsAsync(updatedInstructors)).unwrap();
            addToast('Instructor removed successfully', 'success');
        } catch (error) {
            console.error('Failed to delete instructor:', error);
            addToast('Failed to delete instructor', 'error');
        } finally {
            setIsDeleting(false);
            setDeleteId(null);
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            let updatedInstructors;
            if (editingInstructor) {
                updatedInstructors = instructors.map(i => i.id === editingInstructor.id ? formData : i);
                addToast('Instructor updated successfully', 'success');
            } else {
                updatedInstructors = [formData, ...instructors];
                addToast('Instructor added successfully', 'success');
            }
            await dispatch(updateInstructorsAsync(updatedInstructors)).unwrap();
            setIsModalOpen(false);
        } catch (error) {
            console.error('Failed to save instructor:', error);
            addToast('Failed to save instructor', 'error');
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <h2 className="text-xl font-bold flex items-center gap-2">
                    <Icon name="Users" size={24} className="text-secondary" />
                    Instructors
                </h2>
                <Button variant="default" iconName="Plus" onClick={() => handleOpenModal()}>
                    Add Instructor
                </Button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {instructors.length > 0 ? instructors.map((instructor) => (
                    <div key={instructor.id} className="bg-card border border-border rounded-2xl p-6 flex flex-col gap-4 group relative">
                        <div className="absolute top-4 right-4 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button
                                onClick={() => handleOpenModal(instructor)}
                                className="p-2 bg-muted hover:bg-muted/80 rounded-lg text-primary transition-colors"
                            >
                                <Icon name="Edit2" size={16} />
                            </button>
                            <button
                                onClick={() => handleDeleteClick(instructor.id)}
                                className="p-2 bg-red-50 hover:bg-red-100 text-red-500 rounded-lg transition-colors"
                            >
                                <Icon name="Trash2" size={16} />
                            </button>
                        </div>

                        <div className="flex items-center gap-4">
                            <img
                                src={instructor.avatar || `https://ui-avatars.com/api/?name=${instructor.name}`}
                                alt={instructor.name}
                                className="w-16 h-16 rounded-full object-cover border-2 border-border"
                            />
                            <div>
                                <h3 className="font-bold text-lg leading-tight">{instructor.name}</h3>
                                <p className="text-sm text-secondary font-medium">{instructor.role}</p>
                            </div>
                        </div>
                        <p className="text-sm text-muted-foreground line-clamp-3">{instructor.bio || "No bio available."}</p>

                        <div className="mt-auto pt-4 border-t border-border">
                            {(() => {
                                const promo = getPromoForInstructor(instructor.id);
                                if (promo) {
                                    return (
                                        <div className="flex items-center justify-between p-3 bg-muted/50 rounded-xl mb-3">
                                            <div className="flex items-center gap-2">
                                                <Icon name="Tag" size={14} className="text-primary" />
                                                <span className="text-xs font-bold tracking-wider">{promo.code}</span>
                                                <span className={`text-[9px] font-black uppercase px-1.5 py-0.5 rounded-full ${promo.is_active ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-600'}`}>
                                                    {promo.is_active ? 'Active' : 'Disabled'}
                                                </span>
                                            </div>
                                            <button
                                                onClick={() => handleTogglePromo(promo.id, promo.is_active)}
                                                disabled={togglingPromo === promo.id}
                                                className={`p-1.5 rounded-lg transition-colors ${promo.is_active ? 'text-emerald-600 hover:bg-emerald-50' : 'text-red-500 hover:bg-red-50'}`}
                                            >
                                                {togglingPromo === promo.id ? (
                                                    <div className="w-3.5 h-3.5 border-2 border-current border-t-transparent rounded-full animate-spin" />
                                                ) : (
                                                    <Icon name={promo.is_active ? 'Eye' : 'EyeOff'} size={14} />
                                                )}
                                            </button>
                                        </div>
                                    );
                                }
                                return (
                                    <div className="flex items-center gap-2 p-3 bg-muted/30 rounded-xl mb-3">
                                        <Icon name="Tag" size={14} className="text-muted-foreground" />
                                        <span className="text-xs text-muted-foreground">No promo code assigned</span>
                                    </div>
                                );
                            })()}
                            <div className="flex gap-3">
                            {instructor.socials?.linkedin && (
                                <a href={instructor.socials.linkedin} target="_blank" rel="noreferrer" className="text-muted-foreground hover:text-[#0077b5]">
                                    <Icon name="Linkedin" size={18} />
                                </a>
                            )}
                            {instructor.socials?.twitter && (
                                <a href={instructor.socials.twitter} target="_blank" rel="noreferrer" className="text-muted-foreground hover:text-[#1DA1F2]">
                                    <Icon name="Twitter" size={18} />
                                </a>
                            )}
                            </div>
                        </div>
                    </div>
                )) : (
                    <div className="col-span-full py-12 text-center bg-muted/20 rounded-3xl border border-dashed border-border text-muted-foreground">
                        No instructors found. Add your team members here.
                    </div>
                )}
            </div>

            <Modal
                isOpen={isModalOpen}
                onClose={() => setIsModalOpen(false)}
                title={editingInstructor ? "Edit Instructor" : "Add Instructor"}
                size="md"
            >
                <form onSubmit={handleSubmit} className="space-y-4">
                    <div>
                        <label className="block text-sm font-medium mb-1">Full Name</label>
                        <input
                            required
                            value={formData.name}
                            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                            className="w-full px-4 py-2 bg-muted border border-border rounded-lg focus:ring-2 focus:ring-primary outline-none"
                            placeholder="e.g. Dr. Jane Doe"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium mb-1">Role / Title</label>
                        <input
                            required
                            value={formData.role}
                            onChange={(e) => setFormData({ ...formData, role: e.target.value })}
                            className="w-full px-4 py-2 bg-muted border border-border rounded-lg focus:ring-2 focus:ring-primary outline-none"
                            placeholder="e.g. Senior Lecturer"
                        />
                    </div>
                    <div className="space-y-4">
                        <label className="block text-sm font-medium mb-1">Profile Picture</label>
                        <div className="flex items-center gap-4 p-4 bg-muted/30 border border-dashed border-border rounded-2xl">
                            <div className="w-16 h-16 rounded-full bg-muted border border-border overflow-hidden shrink-0">
                                {formData.avatar ? (
                                    <img src={formData.avatar} alt="Preview" className="w-full h-full object-cover" />
                                ) : (
                                    <div className="w-full h-full flex items-center justify-center text-muted-foreground">
                                        <Icon name="User" size={24} />
                                    </div>
                                )}
                            </div>
                            <div className="flex-1 space-y-2">
                                <div className="relative">
                                    <input
                                        type="file"
                                        accept="image/*"
                                        onChange={handleImageUpload}
                                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                                        disabled={isUploading}
                                    />
                                    <Button variant="outline" size="sm" fullWidth iconName={isUploading ? "Loader2" : "UploadCloud"} className={isUploading ? "animate-pulse" : ""}>
                                        {isUploading ? "Uploading..." : "Upload New Photo"}
                                    </Button>
                                </div>
                                <p className="text-[10px] text-muted-foreground text-center">PNG, JPG or WebP (Max 2MB)</p>
                            </div>
                        </div>
                        <div>
                            <label className="block text-[10px] uppercase font-bold text-muted-foreground mb-1 tracking-wider">Or paste Image URL</label>
                            <input
                                value={formData.avatar}
                                onChange={(e) => setFormData({ ...formData, avatar: e.target.value })}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg focus:ring-2 focus:ring-primary outline-none text-xs"
                                placeholder="https://..."
                            />
                        </div>
                    </div>
                    <div>
                        <label className="block text-sm font-medium mb-1">Bio</label>
                        <textarea
                            value={formData.bio}
                            onChange={(e) => setFormData({ ...formData, bio: e.target.value })}
                            className="w-full px-4 py-2 bg-muted border border-border rounded-lg focus:ring-2 focus:ring-primary outline-none min-h-[100px]"
                            placeholder="Short biography..."
                        />
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium mb-1">LinkedIn URL</label>
                            <input
                                value={formData.socials?.linkedin}
                                onChange={(e) => setFormData({ ...formData, socials: { ...formData.socials, linkedin: e.target.value } })}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg focus:ring-2 focus:ring-primary outline-none"
                                placeholder="Optional"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Twitter URL</label>
                            <input
                                value={formData.socials?.twitter}
                                onChange={(e) => setFormData({ ...formData, socials: { ...formData.socials, twitter: e.target.value } })}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg focus:ring-2 focus:ring-primary outline-none"
                                placeholder="Optional"
                            />
                        </div>
                    </div>

                    <div className="flex justify-end gap-3 pt-4 border-t border-border mt-4">
                        <Button variant="ghost" type="button" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                        <Button variant="default" type="submit">
                            {editingInstructor ? "Save Changes" : "Add Instructor"}
                        </Button>
                    </div>
                </form>
            </Modal>

            <ConfirmationModal
                isOpen={!!deleteId}
                onClose={() => setDeleteId(null)}
                onConfirm={performDelete}
                title="Delete Instructor"
                message="Are you sure? This action cannot be undone."
                type="danger"
                isLoading={isDeleting}
                confirmText="Delete"
            />
        </div>
    );
};

export default InstructorManagement;
