import React, { useState, useEffect, useCallback } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import { useToast } from '../../../contexts/ToastContext';
import { useSelector } from 'react-redux';
import { formatNaira } from '../../../utils/currencyUtils';

const PaymentManagement = () => {
    const { addToast } = useToast();
    const { user } = useSelector((state) => state.auth);
    const academyTracks = useSelector((state) => state.content.academyTracks) || [];
    const [requests, setRequests] = useState([]);
    const [stats, setStats] = useState({ total: 0, pending: 0, confirmed: 0, rejected: 0, unenrolled: 0, totalRevenue: 0, pendingAmount: 0 });
    const [filter, setFilter] = useState('pending');
    const [isLoading, setIsLoading] = useState(true);
    const [actionLoading, setActionLoading] = useState(null);

    const fetchData = useCallback(async () => {
        setIsLoading(true);
        try {
            const [requestsData, statsData] = await Promise.all([
                supabaseService.getPaymentRequests(),
                supabaseService.getPaymentRequestStats(),
            ]);
            setRequests(requestsData);
            setStats(statsData);
        } catch (err) {
            console.error("Failed to fetch payment data:", err);
            addToast("Failed to load payment data", "error");
        } finally {
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchData();

        const channel = supabaseService.supabase.channel('admin_payment_updates');
        channel.on('broadcast', { event: 'PAYMENT_PENDING' }, () => {
            fetchData();
        });
        channel.subscribe();

        return () => { channel.unsubscribe(); };
    }, []);

    const handleConfirm = async (payment) => {
        setActionLoading(payment.id);
        try {
            await supabaseService.confirmPaymentRequest(payment.id, user.id);

            const { enrollUser } = supabaseService;
            if (payment.is_track && payment.track_id) {
                let trackCourseIds = [];
                const track = academyTracks.find(t => String(t.id) === String(payment.track_id));
                if (track?.courses) {
                    trackCourseIds = track.courses.map(String);
                }

                await supabaseService.enrollInTrack(
                    payment.user_id,
                    payment.track_id,
                    trackCourseIds,
                    payment.amount
                );
            } else {
                await enrollUser(payment.user_id, 'academy', payment.course_id, payment.amount);
            }

            // Notify the student in real-time
            supabaseService.supabase.channel(`payment_${payment.user_id}`).send({
                type: 'broadcast',
                event: 'PAYMENT_CONFIRMED',
                payload: {
                    courseId: payment.course_id,
                    courseTitle: payment.course_title,
                    isTrack: payment.is_track,
                    trackId: payment.track_id,
                    amount: payment.amount,
                }
            });

            // Record promo code usage if a promo was applied during checkout
            if (payment.promo_code_id && payment.promo_type === 'platform') {
                try {
                    const originalPrice = payment.amount / (1 - (payment.promo_discount_percent / 100)) || payment.amount;
                    const discountAmt = originalPrice - payment.amount;
                    await supabaseService.recordPlatformPromoUsage({
                        promoCodeId: payment.promo_code_id,
                        userId: payment.user_id,
                        courseId: payment.course_id,
                        courseTitle: payment.course_title,
                        originalPrice: originalPrice,
                        discountAmount: discountAmt,
                        finalPrice: payment.amount,
                        rewardLucCredited: payment.promo_reward_luc || 0,
                        paymentReference: `admin_confirmed_${payment.id}`
                    });
                    if (payment.promo_reward_luc > 0) {
                        const { data: promoCode } = await supabaseService.supabase
                            .from('platform_promo_codes')
                            .select('created_by')
                            .eq('id', payment.promo_code_id)
                            .single();
                        if (promoCode?.created_by) {
                            await supabaseService.processWalletTransaction(
                                promoCode.created_by,
                                payment.promo_reward_luc,
                                'platform_promo_reward',
                                `Promo code reward for ${payment.course_title}`,
                                `promo_reward_${payment.id}`
                            );
                        }
                    }
                } catch (promoErr) {
                    console.error('Failed to record platform promo usage:', promoErr);
                }
            } else if (payment.promo_code_id && payment.promo_type === 'instructor') {
                try {
                    const originalPrice = payment.amount / (1 - (payment.promo_discount_percent / 100)) || payment.amount;
                    const discountAmt = originalPrice - payment.amount;
                    const lucCredit = Math.round(discountAmt / 50);
                    const { data: instrPromo } = await supabaseService.supabase
                        .from('instructor_promo_codes')
                        .select('instructor_id')
                        .eq('id', payment.promo_code_id)
                        .single();
                    if (instrPromo?.instructor_id) {
                        await supabaseService.processWalletTransaction(
                            instrPromo.instructor_id,
                            lucCredit,
                            'instructor_promo_bonus',
                            `Promo code bonus for ${payment.course_title}`,
                            `promo_bonus_${payment.id}`
                        );
                        await supabaseService.recordInstructorPromoUsage(
                            payment.promo_code_id,
                            instrPromo.instructor_id,
                            payment.user_id,
                            payment.course_id,
                            discountAmt,
                            lucCredit
                        );
                    }
                } catch (promoErr) {
                    console.error('Failed to record instructor promo usage:', promoErr);
                }
            }

            addToast(`Payment confirmed! ${payment.user?.full_name || 'Student'} has been enrolled.`, 'success');
            fetchData();
        } catch (err) {
            console.error("Failed to confirm payment:", err);
            addToast("Failed to confirm payment or enroll student", "error");
        } finally {
            setActionLoading(null);
        }
    };

    const handleReject = async (payment) => {
        setActionLoading(payment.id);
        try {
            await supabaseService.rejectPaymentRequest(payment.id, user.id);

            // Notify the student in real-time
            supabaseService.supabase.channel(`payment_${payment.user_id}`).send({
                type: 'broadcast',
                event: 'PAYMENT_REJECTED',
                payload: {
                    courseId: payment.course_id,
                    courseTitle: payment.course_title,
                }
            });

            addToast("Payment rejected.", 'info');
            fetchData();
        } catch (err) {
            console.error("Failed to reject payment:", err);
            addToast("Failed to reject payment", "error");
        } finally {
            setActionLoading(null);
        }
    };

    const handleUnenroll = async (payment) => {
        setActionLoading(payment.id);
        try {
            if (payment.is_track && payment.track_id) {
                let trackCourseIds = [];
                const track = academyTracks.find(t => String(t.id) === String(payment.track_id));
                if (track?.courses) {
                    trackCourseIds = track.courses.map(String);
                }
                await supabaseService.unenrollFromTrack(payment.user_id, payment.track_id, trackCourseIds);
            } else {
                await supabaseService.unenrollUser(payment.user_id, 'academy', payment.course_id);
            }
            await supabaseService.unenrollPaymentRequest(payment.id, user.id);
            addToast(`${payment.user?.full_name || 'Student'} has been unenrolled from ${payment.course_title}.`, 'success');
            fetchData();
        } catch (err) {
            console.error("Failed to unenroll:", err);
            addToast("Failed to unenroll student", "error");
        } finally {
            setActionLoading(null);
        }
    };

    const filteredRequests = filter === 'all' ? requests : requests.filter(r => r.status === filter);

    const statusColors = {
        pending: 'bg-amber-500/10 text-amber-500 border-amber-500/20',
        confirmed: 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20',
        rejected: 'bg-red-500/10 text-red-500 border-red-500/20',
        unenrolled: 'bg-slate-500/10 text-slate-500 border-slate-500/20',
    };

    return (
        <div className="space-y-8">
            {/* Stats Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                <div className="bg-card border border-border rounded-2xl p-6 shadow-xl">
                    <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-xl bg-primary/10 flex items-center justify-center text-primary">
                            <Icon name="CreditCard" size={22} />
                        </div>
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">Total</p>
                            <p className="text-2xl font-black">{stats.total}</p>
                        </div>
                    </div>
                </div>
                <div className="bg-card border border-border rounded-2xl p-6 shadow-xl">
                    <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-xl bg-amber-500/10 flex items-center justify-center text-amber-500">
                            <Icon name="Clock" size={22} />
                        </div>
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">Pending</p>
                            <p className="text-2xl font-black">{stats.pending}</p>
                            <p className="text-xs font-bold text-amber-500">{formatNaira(stats.pendingAmount)}</p>
                        </div>
                    </div>
                </div>
                <div className="bg-card border border-border rounded-2xl p-6 shadow-xl">
                    <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-xl bg-emerald-500/10 flex items-center justify-center text-emerald-500">
                            <Icon name="CheckCircle" size={22} />
                        </div>
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">Confirmed</p>
                            <p className="text-2xl font-black">{stats.confirmed}</p>
                        </div>
                    </div>
                </div>
                <div className="bg-card border border-border rounded-2xl p-6 shadow-xl">
                    <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-xl bg-success/10 flex items-center justify-center text-success">
                            <Icon name="TrendingUp" size={22} />
                        </div>
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">Revenue</p>
                            <p className="text-2xl font-black">{formatNaira(stats.totalRevenue)}</p>
                        </div>
                    </div>
                </div>
            </div>

            {/* Filter Tabs */}
            <div className="flex gap-2 flex-wrap">
                {[
                    { id: 'pending', label: 'Pending', count: stats.pending },
                    { id: 'confirmed', label: 'Confirmed', count: stats.confirmed },
                    { id: 'unenrolled', label: 'Unenrolled', count: stats.unenrolled },
                    { id: 'rejected', label: 'Rejected', count: stats.rejected },
                    { id: 'all', label: 'All', count: stats.total },
                ].map(tab => (
                    <button
                        key={tab.id}
                        onClick={() => setFilter(tab.id)}
                        className={`px-4 py-2 rounded-xl text-xs font-black italic uppercase tracking-widest transition-all ${
                            filter === tab.id
                                ? 'bg-primary text-white shadow-lg shadow-primary/20'
                                : 'bg-card border border-border text-muted-foreground hover:text-foreground'
                        }`}
                    >
                        {tab.label} ({tab.count})
                    </button>
                ))}
            </div>

            {/* Payment Requests Table */}
            {isLoading ? (
                <div className="flex items-center justify-center py-20">
                    <div className="w-12 h-12 border-4 border-primary/20 border-t-primary rounded-full animate-spin" />
                </div>
            ) : filteredRequests.length === 0 ? (
                <div className="text-center py-20 bg-card border border-border rounded-2xl">
                    <Icon name="Inbox" size={48} className="text-muted-foreground mx-auto mb-4" />
                    <p className="font-bold text-muted-foreground">No {filter === 'all' ? '' : filter} payment requests</p>
                </div>
            ) : (
                <div className="space-y-3">
                    {filteredRequests.map(payment => (
                        <div key={payment.id} className="bg-card border border-border rounded-2xl p-6 shadow-xl hover:shadow-2xl transition-all">
                            <div className="flex flex-col sm:flex-row sm:items-center gap-4">
                                {/* Student Info */}
                                <div className="flex items-center gap-3 flex-1 min-w-0">
                                    <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center text-primary shrink-0 overflow-hidden">
                                        {payment.user?.avatar_url ? (
                                            <img src={payment.user.avatar_url} alt="" className="w-full h-full object-cover" />
                                        ) : (
                                            <Icon name="User" size={18} />
                                        )}
                                    </div>
                                    <div className="min-w-0">
                                        <p className="font-bold text-sm truncate">{payment.user?.full_name || 'Unknown'}</p>
                                        <p className="text-xs text-muted-foreground truncate">{payment.user?.email || payment.user_id}</p>
                                    </div>
                                </div>

                                {/* Course Info */}
                                <div className="flex-1 min-w-0">
                                    <p className="font-bold text-sm truncate">{payment.course_title}</p>
                                    <p className="text-xs text-muted-foreground">
                                        {payment.is_track ? 'Track' : 'Course'} · {new Date(payment.created_at).toLocaleString()}
                                    </p>
                                </div>

                                {/* Amount */}
                                <div className="text-right shrink-0">
                                    <p className="text-lg font-black text-primary">{formatNaira(payment.amount)}</p>
                                    {payment.bank && (
                                        <span className={`inline-block px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-widest border mb-1 ${
                                            payment.bank === 'opay' ? 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20' : 'bg-purple-500/10 text-purple-500 border-purple-500/20'
                                        }`}>
                                            {payment.bank}
                                        </span>
                                    )}
                                    <span className={`inline-block px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-widest border ${statusColors[payment.status]}`}>
                                        {payment.status}
                                    </span>
                                </div>

                                {/* Actions */}
                                {payment.status === 'pending' && (
                                    <div className="flex gap-2 shrink-0">
                                        <Button
                                            onClick={() => handleConfirm(payment)}
                                            loading={actionLoading === payment.id}
                                            className="bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 text-xs font-black italic rounded-xl"
                                        >
                                            CONFIRM
                                        </Button>
                                        <Button
                                            onClick={() => handleReject(payment)}
                                            loading={actionLoading === payment.id}
                                            variant="outline"
                                            className="text-red-500 border-red-200 hover:bg-red-50 px-4 py-2 text-xs font-black italic rounded-xl"
                                        >
                                            REJECT
                                        </Button>
                                    </div>
                                )}
                                {payment.status === 'confirmed' && (
                                    <div className="flex gap-2 shrink-0">
                                        <Button
                                            onClick={() => handleUnenroll(payment)}
                                            loading={actionLoading === payment.id}
                                            variant="outline"
                                            className="text-red-500 border-red-200 hover:bg-red-50 px-4 py-2 text-xs font-black italic rounded-xl"
                                        >
                                            UNENROLL
                                        </Button>
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
};

export default PaymentManagement;
