import React, { useMemo, useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import { supabaseService } from '../../../services/supabaseService';
import AnalyticsChart from './AnalyticsChart';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import { useToast } from '../../../contexts/ToastContext';

const AnalyticsManagement = () => {
    const opportunities = useSelector((state) => state.content.allOpportunities);
    const [users, setUsers] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [gaId, setGaId] = useState('');
    const [isSaving, setIsSaving] = useState(false);
    const { addToast } = useToast();

    const [platformMetrics, setPlatformMetrics] = useState([]);
    const [isMetricsLoading, setIsMetricsLoading] = useState(true);

    useEffect(() => {
        const fetchData = async () => {
            try {
                const [profiles, siteContent, metrics] = await Promise.all([
                    supabaseService.getProfiles(),
                    supabaseService.getSiteContent(),
                    supabaseService.getPlatformMetrics(30) // Last 30 days
                ]);
                
                setUsers(profiles);
                setPlatformMetrics(metrics || []);

                if (siteContent.analytics_config) {
                    setGaId(siteContent.analytics_config.measurementId || '');
                }
            } catch (error) {
                console.error("Error fetching analytics data:", error);
            } finally {
                setIsLoading(false);
                setIsMetricsLoading(false);
            }
        };
        fetchData();
    }, []);

    const dailyPulseData = useMemo(() => {
        if (!platformMetrics.length) return [];
        
        return [...platformMetrics].reverse().map(m => ({
            date: new Date(m.metric_date).toLocaleDateString(undefined, { month: 'short', day: 'numeric' }),
            total: m.total_visits || 0,
            scholars: m.auth_visits || 0,
            guests: m.guest_visits || 0
        }));
    }, [platformMetrics]);

    const handleSaveGaConfig = async () => {
        setIsSaving(true);
        try {
            await supabaseService.updateSiteContent('analytics_config', { measurementId: gaId });
            addToast("Analytics configuration updated. Stream will restart on next reload.", "success");
        } catch (error) {
            addToast("Failed to save configuration.", "error");
        } finally {
            setIsSaving(false);
        }
    };

    // Process opportunities by category
    const categoryData = useMemo(() => {
        const counts = {};
        opportunities.forEach(opp => {
            const cat = opp.category || 'Uncategorized';
            counts[cat] = (counts[cat] || 0) + 1;
        });
        return Object.entries(counts).map(([name, count]) => ({
            name: name.charAt(0).toUpperCase() + name.slice(1).replace('_', ' '),
            value: count
        })).sort((a, b) => b.value - a.value);
    }, [opportunities]);

    // Calculate real monthly growth data
    const growthData = useMemo(() => {
        const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
        const currentYear = new Date().getFullYear();

        const monthlyStats = months.map((month, index) => {
            const userCount = users.filter(u => {
                const date = new Date(u.created_at);
                return date.getMonth() === index && date.getFullYear() === currentYear;
            }).length;

            const oppCount = opportunities.filter(o => {
                const date = new Date(o.created_at);
                return date.getMonth() === index && date.getFullYear() === currentYear;
            }).length;

            return { name: month, users: userCount, opportunities: oppCount };
        });

        // Slice to show only months up to current
        return monthlyStats.slice(0, new Date().getMonth() + 1);
    }, [users, opportunities]);

    // Insight calculations
    const insights = useMemo(() => {
        const now = new Date();
        const thisMonth = users.filter(u => new Date(u.created_at).getMonth() === now.getMonth()).length;
        const lastMonth = users.filter(u => new Date(u.created_at).getMonth() === (now.getMonth() - 1 + 12) % 12).length;

        let userGrowthMsg = "Growing steady.";
        if (lastMonth > 0) {
            const growth = ((thisMonth - lastMonth) / lastMonth) * 100;
            userGrowthMsg = `User signups ${growth >= 0 ? 'increased' : 'decreased'} by ${Math.abs(growth).toFixed(1)}% this month.`;
        }

        return {
            userGrowth: userGrowthMsg,
            totalViews: opportunities.reduce((acc, curr) => acc + (curr.views || 0), 0).toLocaleString(),
            avgApplicants: opportunities.length > 0
                ? (opportunities.reduce((acc, curr) => acc + (curr.applicants || 0), 0) / opportunities.length).toFixed(1)
                : 0
        };
    }, [users, opportunities]);

    return (
        <div className="space-y-12">
            {/* Internal Pulse Command Center */}
            <div className="bg-slate-900 border border-white/10 rounded-[3rem] p-8 md:p-12 shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 w-96 h-96 bg-primary/5 blur-[120px] -mr-48 -mt-48" />
                
                <div className="relative z-10">
                    <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-12">
                        <div>
                            <div className="inline-flex items-center gap-2 px-3 py-1 bg-primary/10 border border-primary/20 rounded-lg text-primary text-[10px] font-black uppercase tracking-[0.2em] mb-4">
                                <div className="w-1.5 h-1.5 bg-primary rounded-full animate-pulse" />
                                Internal Precision Sentinel
                            </div>
                            <h2 className="text-3xl md:text-5xl font-black text-white italic tracking-tighter leading-none">
                                PLATFORM <span className="text-primary">HEARTBEAT.</span>
                            </h2>
                        </div>
                        <div className="flex gap-4">
                            <div className="bg-white/5 border border-white/10 rounded-2xl p-4 min-w-[140px] text-center">
                                <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Today's Pulse</p>
                                <p className="text-2xl font-black text-white italic">
                                    {platformMetrics.find(m => m.metric_date === new Date().toISOString().split('T')[0])?.total_visits || 0}
                                </p>
                            </div>
                            <div className="bg-primary/10 border border-primary/20 rounded-2xl p-4 min-w-[140px] text-center">
                                <p className="text-[10px] font-black text-primary/60 uppercase tracking-widest mb-1">Scholar Active</p>
                                <p className="text-2xl font-black text-primary italic">
                                    {platformMetrics.find(m => m.metric_date === new Date().toISOString().split('T')[0])?.auth_visits || 0}
                                </p>
                            </div>
                        </div>
                    </div>

                    <div className="h-[400px] w-full">
                        {isMetricsLoading ? (
                            <div className="w-full h-full flex items-center justify-center text-slate-500 font-bold uppercase tracking-widest">
                                Calibrating Pulse...
                            </div>
                        ) : dailyPulseData.length > 0 ? (
                            <AnalyticsChart
                                title="Daily Traffic Velocity (Last 30 Days)"
                                data={dailyPulseData}
                                type="area"
                                dataKey="total"
                                secondDataKey="scholars"
                                color="var(--color-primary)"
                                secondColor="var(--color-secondary)"
                            />
                        ) : (
                            <div className="w-full h-full flex flex-col items-center justify-center text-slate-500 border-2 border-dashed border-white/5 rounded-3xl">
                                <Icon name="Activity" size={48} className="mb-4 opacity-20" />
                                <p className="font-bold uppercase tracking-widest text-xs">Waiting for first pulse...</p>
                            </div>
                        )}
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {/* Platform Growth */}
                <AnalyticsChart
                    title="User Growth (Monthly)"
                    data={growthData}
                    type="area"
                    dataKey="users"
                    color="var(--color-primary)"
                />

                {/* Opportunity Trends */}
                <AnalyticsChart
                    title="Opportunities Posted"
                    data={growthData}
                    type="line"
                    dataKey="opportunities"
                    color="var(--color-secondary)"
                />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {/* Category Distribution */}
                <AnalyticsChart
                    title="Opportunities by Category"
                    data={categoryData}
                    type="bar"
                    dataKey="value"
                    color="var(--color-brand-purple)"
                />

                {/* Total Platform Visibility */}
                <div className="bg-card p-6 rounded-2xl shadow-sm border border-border flex flex-col justify-center text-center">
                    <div className="w-16 h-16 rounded-2xl bg-brand-blue/10 text-brand-blue flex items-center justify-center mx-auto mb-4">
                        <Icon name="Eye" size={32} />
                    </div>
                    <h3 className="text-4xl font-black text-foreground mb-2">{insights.totalViews}</h3>
                    <p className="text-muted-foreground font-medium uppercase tracking-wider text-sm">Total Opportunity Views</p>
                    <div className="mt-6 pt-6 border-t border-border">
                        <p className="text-sm text-muted-foreground">Across all {opportunities.length} active listings</p>
                    </div>
                </div>
            </div>

            {/* Insight Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-card p-6 rounded-2xl shadow-sm border border-border">
                    <div className="w-12 h-12 rounded-xl bg-success/10 flex items-center justify-center mb-4 text-success">
                        <Icon name="TrendingUp" size={24} />
                    </div>
                    <h4 className="font-bold text-foreground mb-1">Growth Insight</h4>
                    <p className="text-sm text-muted-foreground">{insights.userGrowth}</p>
                </div>

                <div className="bg-card p-6 rounded-2xl shadow-sm border border-border">
                    <div className="w-12 h-12 rounded-xl bg-accent/10 flex items-center justify-center mb-4 text-accent">
                        <Icon name="Target" size={24} />
                    </div>
                    <h4 className="font-bold text-foreground mb-1">Top Category</h4>
                    <p className="text-sm text-muted-foreground">
                        {categoryData.length > 0
                            ? `${categoryData[0].name} is currently your most active category with ${categoryData[0].value} listings.`
                            : "No category data available yet."}
                    </p>
                </div>

                <div className="bg-card p-6 rounded-2xl shadow-sm border border-border">
                    <div className="w-12 h-12 rounded-xl bg-brand-purple/10 flex items-center justify-center mb-4 text-brand-purple">
                        <Icon name="Users" size={24} />
                    </div>
                    <h4 className="font-bold text-foreground mb-1">Engagement</h4>
                    <p className="text-sm text-muted-foreground">You average {insights.avgApplicants} applicant conversions per opportunity listing.</p>
                </div>
            </div>

            {/* Tracking Configuration */}
            <div className="bg-card p-8 rounded-[2.5rem] shadow-sm border border-border mt-8">
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                    <div className="space-y-1">
                        <h3 className="text-xl font-black text-foreground italic uppercase tracking-tighter">
                            Tracking <span className="text-primary">Configuration.</span>
                        </h3>
                        <p className="text-sm text-muted-foreground font-medium">Manage the global analytics stream and measurement IDs.</p>
                    </div>
                    <div className="flex flex-col md:flex-row items-center gap-4 w-full md:w-auto">
                        <div className="relative w-full md:w-80">
                            <Icon name="Target" size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-muted-foreground" />
                            <input 
                                type="text"
                                placeholder="G-XXXXXXXXXX"
                                value={gaId}
                                onChange={(e) => setGaId(e.target.value)}
                                className="w-full bg-muted/50 border border-border rounded-xl py-3 pl-12 pr-4 text-sm font-bold focus:outline-none focus:border-primary transition-all"
                            />
                        </div>
                        <Button 
                            onClick={handleSaveGaConfig}
                            loading={isSaving}
                            className="w-full md:w-auto px-8 font-black italic rounded-xl"
                        >
                            UPDATE STREAM
                        </Button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default AnalyticsManagement;
