import React, { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { supabaseService } from '../../../services/supabaseService';
import Button from '../../../components/ui/Button';
import { normalizeId } from '../../../utils/idUtils';
import { durationToSeconds } from '../../../utils/courseUtils';
import Icon from '../../../components/AppIcon';
import { cn } from '../../../utils/cn';

const StudentDetailView = ({ user, onBack }) => {
    const [isLoading, setIsLoading] = useState(true);
    const [details, setDetails] = useState({ enrollments: [], badges: [] });

    // Get content from Redux to resolve IDs to Titles
    const academy = useSelector((state) => state.content.academy) || [];
    const vault = useSelector((state) => state.content.vault) || [];
    const academyTracks = useSelector((state) => state.content.academyTracks) || [];

    const [trackAttendance, setTrackAttendance] = useState({});
    const [attendanceLoading, setAttendanceLoading] = useState(true);

    useEffect(() => {
        if (!user?.id) return;

        fetchDetails(true);
        loadTrackAttendance();

        // Real-time subscription for dynamic progress updates (matching CoursePlayer behavior)
        const channel = supabaseService.subscribeToUserActivity(user.id, (payload) => {
            // Trigger a silent refresh when database changes are detected
            fetchDetails(false);
            loadTrackAttendance();
        });

        return () => {
            if (channel) supabaseService.unsubscribe(channel);
        };
    }, [user?.id]);

    const fetchDetails = async (showLoading = true) => {
        if (showLoading) setIsLoading(true);
        try {
            const data = await supabaseService.getStudentDetails(user.id);
            setDetails(data);
        } catch (error) {
            console.error('Failed to fetch student details:', error);
        } finally {
            if (showLoading) setIsLoading(false);
        }
    };

    const loadTrackAttendance = async () => {
        if (!user?.id || !academyTracks?.length) return;
        setAttendanceLoading(true);
        const results = {};
        for (const track of academyTracks) {
            const trackCourseIds = (track.courses || []).map(id => String(id));
            try {
                const stats = await supabaseService.getTrackAttendanceStats(user.id, trackCourseIds);
                if (stats.total > 0) results[track.id] = { ...stats, trackTitle: track.title };
            } catch (err) {
                console.error('Failed to load attendance for track:', track.title, err);
            }
        }
        setTrackAttendance(results);
        setAttendanceLoading(false);
    };

    const getCourseInfo = (type, itemId) => {
        const list = type === 'academy' ? academy : vault;
        const normalizedItemId = normalizeId(itemId);
        const item = list.find(i => normalizeId(i.id) === normalizedItemId);
        return {
            title: item?.title || 'Unknown Item',
            thumbnail: item?.image || item?.thumbnail || '',
            category: item?.category || 'General'
        };
    };

    const calculateTrueProgress = (enrollment) => {
        const itemId = normalizeId(enrollment.item_id);
        const type = enrollment.type;
        const list = type === 'academy' ? academy : vault;
        const mainItem = list.find(i => normalizeId(i.id) === itemId);

        if (!mainItem) return enrollment.progress || 0;

        // Match the lesson discovery logic from CoursePlayer
        let allLessons = [];
        if (mainItem.content && mainItem.content.length > 0) {
            mainItem.content.forEach((mod) => {
                if (mod.lessons) {
                    mod.lessons.forEach((lesson, lessonIdx) => {
                        allLessons.push({
                            ...lesson,
                            id: normalizeId(lesson.id || `${mod.module}-${lessonIdx}`)
                        });
                    });
                }
            });
        } else if (Array.isArray(mainItem.lessons)) {
            allLessons = mainItem.lessons.map(l => ({ ...l, id: normalizeId(l.id) }));
        } else {
            // Single video item
            allLessons = [{
                id: normalizeId(`l-${mainItem.id}`),
                duration: mainItem.duration
            }];
        }

        if (allLessons.length === 0) return enrollment.progress || 0;

        let totalPoints = 0;
        allLessons.forEach(lesson => {
            const lp = details.granularProgress?.find(p => normalizeId(p.lesson_id) === lesson.id);
            if (lp) {
                if (lp.completed) {
                    totalPoints += 1;
                } else {
                    const durationSec = durationToSeconds(lesson.duration);
                    if (durationSec > 0 && lp.last_timestamp > 0) {
                        // Max 0.9 points for uncompleted lesson
                        const lessonPoints = Math.min(0.9, lp.last_timestamp / durationSec);
                        totalPoints += lessonPoints;
                    }
                }
            }
        });

        const calculated = Math.round((totalPoints / allLessons.length) * 100);
        return Math.min(100, Math.max(enrollment.progress || 0, calculated));
    };

    const totalSpent = details.enrollments?.reduce((acc, curr) => acc + (curr.amount_paid || 0), 0) || 0;

    // Derived states using True Progress
    const enrichedEnrollments = details.enrollments?.map(e => {
        const trueProgress = calculateTrueProgress(e);
        return {
            ...e,
            progress: trueProgress,
            calculatedStatus: trueProgress === 100 ? 'completed' : 'active'
        };
    }) || [];

    const completedCourses = enrichedEnrollments.filter(e => e.calculatedStatus === 'completed').length;
    const inProgressCourses = enrichedEnrollments.filter(e => e.calculatedStatus === 'active').length;

    return (
        <div className="bg-card rounded-2xl shadow-[0_4px_12px_rgba(27,54,93,0.08)]">
            <div className="p-4 md:p-6 border-b border-border flex items-center gap-4">
                <Button variant="ghost" size="sm" iconName="ArrowLeft" onClick={onBack}>
                    Back to Users
                </Button>
                <h2 className="text-xl font-bold">Student Profile</h2>
            </div>

            <div className="p-4 md:p-8 max-w-5xl mx-auto space-y-8">
                {/* Header User Info */}
                <div className="flex flex-col md:flex-row items-center gap-6 p-6 bg-muted/30 rounded-2xl border border-border">
                    <img
                        src={user?.avatar}
                        alt={user?.name}
                        className="w-24 h-24 rounded-full object-cover border-4 border-card shadow-sm"
                    />
                    <div className="flex-1 text-center md:text-left">
                        <h3 className="text-2xl font-bold mb-1">{user?.name}</h3>
                        <p className="text-sm text-muted-foreground mb-3">{user?.email}</p>
                        <div className="flex flex-wrap items-center justify-center md:justify-start gap-2">
                            {/* Role Badges */}
                            {(() => {
                                const roles = Array.isArray(user?.roles) ? user.roles : (user?.role ? [user.role] : []);
                                if (roles.length === 0) roles.push('user');

                                const roleConfig = {
                                    founder: { bg: 'bg-primary/20', text: 'text-primary', label: 'Founder', icon: 'Crown' },
                                    admin: { bg: 'bg-red-500/10', text: 'text-red-500', label: 'Admin', icon: 'Shield' },
                                    contributor: { bg: 'bg-blue-500/10', text: 'text-blue-500', label: 'Contributor', icon: 'Users' },
                                    curator: { bg: 'bg-green-500/10', text: 'text-green-500', label: 'Curator', icon: 'Search' },
                                    tutor: { bg: 'bg-purple-500/10', text: 'text-purple-500', label: 'Tutor', icon: 'BookOpen' },
                                    ambassador: { bg: 'bg-orange-500/10', text: 'text-orange-500', label: 'Ambassador', icon: 'Award' },
                                    user: { bg: 'bg-muted', text: 'text-muted-foreground', label: 'Scholar', icon: 'User' }
                                };

                                return roles.map(role => {
                                    const config = roleConfig?.[role] || roleConfig?.user;
                                    return (
                                        <span key={role} className={`inline - flex items - center gap - 1.5 px - 3 py - 1 rounded - full text - [10px] font - bold uppercase tracking - wider ${config.bg} ${config.text} border border - current / 10 shadow - sm`}>
                                            <Icon name={config.icon} size={12} />
                                            {config.label}
                                        </span>
                                    );
                                });
                            })()}

                            <span className="text-[10px] font-bold text-muted-foreground flex items-center gap-1.5 px-3 py-1 bg-background rounded-full border border-border">
                                <Icon name="Calendar" size={12} /> Joined {user?.joinedDate}
                            </span>
                        </div>
                        {user?.demographics && (
                            <div className="flex flex-wrap items-center justify-center md:justify-start gap-4 mt-4 text-xs font-medium text-muted-foreground bg-background/80 p-3 rounded-xl border border-border/50 shadow-sm">
                                {user.demographics.gender !== 'Not specified' && <div className="flex items-center gap-1.5"><Icon name="User" size={14} className="text-primary/70" /> {user.demographics.gender}</div>}
                                {user.demographics.ageRange !== 'Not specified' && <div className="flex items-center gap-1.5"><Icon name="Clock" size={14} className="text-primary/70" /> {user.demographics.ageRange}</div>}
                                {user.demographics.demography !== 'Not specified' && <div className="flex items-center gap-1.5"><Icon name="Briefcase" size={14} className="text-primary/70" /> {user.demographics.demography}</div>}
                                {user.demographics.country !== 'Not specified' && <div className="flex items-center gap-1.5"><Icon name="MapPin" size={14} className="text-primary/70" /> {user.demographics.country}</div>}
                                {user.demographics.phone !== 'Not specified' && <div className="flex items-center gap-1.5"><Icon name="Phone" size={14} className="text-primary/70" /> {user.demographics.phone}</div>}
                            </div>
                        )}
                    </div>
                    <div className="w-full md:w-auto text-center md:text-right p-4 bg-background rounded-xl border border-border shadow-sm">
                        <p className="text-xs text-muted-foreground uppercase font-bold mb-1">Total Value</p>
                        <p className="text-3xl font-black text-primary truncate max-w-[200px] md:max-w-none mx-auto">
                            ₦{totalSpent.toLocaleString()}
                        </p>
                    </div>
                </div>

                {isLoading ? (
                    <div className="py-24 text-center text-muted-foreground flex flex-col items-center">
                        <Icon name="RefreshCw" size={32} className="animate-spin mb-4 opacity-50" />
                        <p className="font-medium">Loading student records...</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                        {/* Left Column: Enrollments */}
                        <div className="lg:col-span-2 space-y-6">
                            <div className="flex items-center justify-between">
                                <h4 className="font-bold text-lg flex items-center gap-2">
                                    <Icon name="Zap" size={20} className="text-secondary" />
                                    Learning Journey
                                </h4>
                                <span className="text-xs font-bold text-muted-foreground bg-muted px-2 py-1 rounded-full">
                                    {details.enrollments?.length || 0} Items
                                </span>
                            </div>

                            <div className="space-y-4">
                                {enrichedEnrollments.length > 0 ? enrichedEnrollments.map((enrollment) => {
                                    const info = getCourseInfo(enrollment.type, enrollment.item_id);
                                    if (!info) return null;

                                    const progress = enrollment.progress;
                                    const status = enrollment.calculatedStatus;

                                    return (
                                        <div key={enrollment.id} className="group p-4 bg-card border border-border hover:border-primary/50 rounded-xl transition-all shadow-sm hover:shadow-md">
                                            <div className="flex gap-4">
                                                <div className="w-20 h-20 rounded-lg overflow-hidden bg-muted flex-shrink-0 relative">
                                                    {info.thumbnail ? (
                                                        <img src={info.thumbnail} alt="" className="w-full h-full object-cover" />
                                                    ) : (
                                                        <div className="w-full h-full flex items-center justify-center text-muted-foreground bg-secondary/10">
                                                            <Icon name={enrollment.type === 'academy' ? 'BookOpen' : 'Zap'} size={24} className="text-secondary" />
                                                        </div>
                                                    )}
                                                    {status === 'completed' && (
                                                        <div className="absolute inset-0 bg-emerald-500/80 flex items-center justify-center backdrop-blur-[1px]">
                                                            <Icon name="Check" size={24} className="text-white" />
                                                        </div>
                                                    )}
                                                </div>
                                                <div className="flex-1 min-w-0 flex flex-col justify-between">
                                                    <div>
                                                        <div className="flex justify-between items-start mb-1">
                                                            <h5 className="font-bold text-base line-clamp-1 pr-2 text-foreground" title={info.title}>{info.title}</h5>
                                                            <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full uppercase tracking-wider flex-shrink-0 ${status === 'completed' ? 'bg-emerald-500/10 text-emerald-600' : 'bg-blue-500/10 text-blue-600'
                                                                } `}>
                                                                {status}
                                                            </span>
                                                        </div>
                                                        <p className="text-xs text-muted-foreground uppercase font-bold tracking-wide flex items-center gap-1.5">
                                                            <Icon name={enrollment.type === 'academy' ? 'BookOpen' : 'Zap'} size={12} />
                                                            {enrollment.type === 'academy' ? 'Academy' : 'Quick Win'}
                                                            <span className="w-1 h-1 rounded-full bg-muted-foreground/30" />
                                                            {info.category}
                                                        </p>
                                                    </div>

                                                    <div className="space-y-1.5 mt-2">
                                                        <div className="flex justify-between text-xs font-bold text-muted-foreground">
                                                            <span>Progress</span>
                                                            <span className={status === 'completed' ? 'text-emerald-600' : 'text-primary'}>{progress}%</span>
                                                        </div>
                                                        <div className="w-full h-1.5 bg-muted rounded-full overflow-hidden">
                                                            <div
                                                                className={`h-full transition-all duration-1000 ease-out rounded-full ${status === 'completed' ? 'bg-emerald-500' : 'bg-primary'} `}
                                                                style={{ width: `${progress}%` }}
                                                            />
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    );
                                }) : (
                                    <div className="text-center py-12 bg-muted/20 border-2 border-dashed border-border rounded-2xl">
                                        <Icon name="BookOpen" size={48} className="mx-auto mb-3 text-muted-foreground/30" />
                                        <p className="text-muted-foreground font-medium">No active enrollments found.</p>
                                        <p className="text-xs text-muted-foreground mt-1">Enroll this student in a course to see progress here.</p>
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Right Column: Stats & Badges */}
                        <div className="space-y-6">
                            {/* Stats Cards */}
                            <div className="grid grid-cols-2 gap-3">
                                <div className="p-4 bg-emerald-50 border border-emerald-100 rounded-xl flex flex-col items-center justify-center text-center">
                                    <div className="w-10 h-10 rounded-full bg-emerald-100 flex items-center justify-center text-emerald-600 mb-2">
                                        <Icon name="CheckCircle" size={20} />
                                    </div>
                                    <div className="text-2xl font-black text-emerald-800">{completedCourses}</div>
                                    <div className="text-[10px] font-bold text-emerald-600 uppercase tracking-wide">Completed</div>
                                </div>
                                <div className="p-4 bg-blue-50 border border-blue-100 rounded-xl flex flex-col items-center justify-center text-center">
                                    <div className="w-10 h-10 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 mb-2">
                                        <Icon name="Activity" size={20} />
                                    </div>
                                    <div className="text-2xl font-black text-blue-800">{inProgressCourses}</div>
                                    <div className="text-[10px] font-bold text-blue-600 uppercase tracking-wide">In Progress</div>
                                </div>
                            </div>

                            {/* Badges Section */}
                            <div className="bg-card border border-border rounded-2xl p-5 shadow-sm">
                                <h4 className="font-bold text-sm mb-4 flex items-center gap-2">
                                    <Icon name="Award" size={18} className="text-amber-500" />
                                    Achievements
                                    <span className="bg-amber-100 text-amber-700 text-[10px] px-1.5 py-0.5 rounded-full ml-auto">
                                        {details.badges?.length || 0}
                                    </span>
                                </h4>

                                {details.badges?.length > 0 ? (
                                    <div className="grid grid-cols-2 gap-3">
                                        {details.badges.map((badge, idx) => (
                                            <div key={idx} className="p-3 bg-gradient-to-br from-amber-50/50 to-orange-50/50 border border-amber-100 rounded-xl flex flex-col items-center text-center hover:scale-[1.02] transition-transform cursor-default" title={badge.description}>
                                                <div className="w-8 h-8 rounded-full bg-amber-100 flex items-center justify-center text-amber-600 mb-2 ring-2 ring-white shadow-sm">
                                                    <Icon name={badge.icon || 'Star'} size={14} />
                                                </div>
                                                <h5 className="font-bold text-xs truncate w-full">{badge.name}</h5>
                                                <p className="text-[10px] text-muted-foreground mt-0.5">
                                                    {new Date(badge.awarded_at).toLocaleDateString()}
                                                </p>
                                            </div>
                                        ))}
                                    </div>
                                ) : (
                                    <div className="text-center py-8 text-sm text-muted-foreground">
                                        <div className="w-12 h-12 bg-muted rounded-full flex items-center justify-center mx-auto mb-2 opacity-50">
                                            <Icon name="Award" size={24} />
                                        </div>
                                        <p>No badges earned yet.</p>
                                    </div>
                                )}
                            </div>

                            {/* Track Attendance Overview */}
                            {Object.keys(trackAttendance).length > 0 && (
                                <div className="bg-card border border-border rounded-2xl p-5 shadow-sm">
                                    <h4 className="font-bold text-sm mb-4 flex items-center gap-2">
                                        <Icon name="ClipboardCheck" size={18} className="text-emerald-500" />
                                        Track Attendance
                                        {attendanceLoading && <div className="w-3 h-3 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin" />}
                                    </h4>
                                    <div className="space-y-3">
                                        {Object.values(trackAttendance).map(stat => (
                                            <div key={stat.trackTitle} className={cn(
                                                'p-3 rounded-xl border',
                                                stat.percentage >= 70 ? 'bg-emerald-500/5 border-emerald-500/20' : 'bg-red-500/5 border-red-500/20'
                                            )}>
                                                <div className="flex justify-between items-center mb-1">
                                                    <span className="text-xs font-bold truncate">{stat.trackTitle}</span>
                                                    <span className={cn('text-xs font-black', stat.percentage >= 70 ? 'text-emerald-600' : 'text-red-600')}>
                                                        {stat.percentage}%
                                                    </span>
                                                </div>
                                                <div className="h-1.5 w-full bg-muted rounded-full overflow-hidden">
                                                    <div className={cn('h-full transition-all rounded-full', stat.percentage >= 70 ? 'bg-emerald-500' : 'bg-red-500')}
                                                        style={{ width: `${stat.percentage}%` }} />
                                                </div>
                                                <div className="flex justify-between mt-1">
                                                    <span className="text-[10px] text-muted-foreground">{stat.attended}/{stat.total} sessions</span>
                                                    <span className={cn('text-[9px] font-bold uppercase', stat.percentage >= 70 ? 'text-emerald-600' : 'text-red-500')}>
                                                        {stat.percentage >= 70 ? '✓ Meets 70%' : `${70 - stat.percentage}% needed`}
                                                    </span>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default StudentDetailView;
