import React, { useState, useEffect, useCallback } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { supabaseService } from '../../../services/supabaseService';
import { generateAttendanceCode, hashAttendanceCode } from '../../../utils/cryptoUtils';
import Button from '../../../components/ui/Button';
import Icon from '../../../components/AppIcon';
import Modal from '../../../components/ui/Modal';
import { useToast } from '../../../contexts/ToastContext';

const DAY_NAMES = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const DAY_OPTIONS = [1, 2, 3, 4, 5, 6]; // Mon-Sat (skip Sunday)

const TrackCourseSchedule = () => {
    const navigate = useNavigate();
    const { addToast } = useToast();
    const user = useSelector((state) => state.auth.user);
    const tracks = useSelector((state) => state.content.academyTracks) || [];
    const courses = useSelector((state) => state.content.academy) || [];

    const [selectedTrackId, setSelectedTrackId] = useState(null);
    const [schedule, setSchedule] = useState(null);
    const [sessions, setSessions] = useState([]);
    const [attendanceData, setAttendanceData] = useState({});
    const [loading, setLoading] = useState(false);
    const [saving, setSaving] = useState(false);
    const [openingSession, setOpeningSession] = useState(null);

    const [startDate, setStartDate] = useState('');
    const [selectedDays, setSelectedDays] = useState([1, 3, 5]);
    const [expandedCourse, setExpandedCourse] = useState(null);

    const selectedTrack = tracks.find(t => String(t.id) === String(selectedTrackId));
    const trackCourseIds = selectedTrack?.courses || [];
    const trackCourses = trackCourseIds.map(id => courses.find(c => String(c.id) === String(id))).filter(Boolean);

    const loadSchedule = useCallback(async () => {
        if (!selectedTrackId) return;
        setLoading(true);
        try {
            const data = await supabaseService.getTrackScheduleWithAttendance(selectedTrackId, trackCourseIds);
            setSchedule(data.schedule);
            setSessions(data.sessions || []);
            setAttendanceData(data.attendanceData || {});
            if (data.schedule) {
                setStartDate(data.schedule.start_date);
                setSelectedDays(data.schedule.session_days || [1, 3, 5]);
            }
        } catch (err) {
            console.error('Failed to load schedule:', err);
        } finally {
            setLoading(false);
        }
    }, [selectedTrackId, trackCourseIds]);

    useEffect(() => {
        if (selectedTrackId) loadSchedule();
    }, [selectedTrackId, loadSchedule]);

    const handleSaveSchedule = async () => {
        if (!startDate || selectedDays.length === 0) {
            addToast('Please select a start date and at least one session day', 'error');
            return;
        }
        setSaving(true);
        try {
            await supabaseService.setTrackSchedule(selectedTrackId, startDate, selectedDays);
            addToast('Schedule saved successfully!', 'success');
            await loadSchedule();
        } catch (err) {
            console.error('Failed to save schedule:', err);
            addToast('Failed to save schedule', 'error');
        } finally {
            setSaving(false);
        }
    };

    const handleDeleteSchedule = async () => {
        if (!confirm('Are you sure you want to delete this schedule? This will not delete any attendance records.')) return;
        try {
            await supabaseService.deleteTrackSchedule(selectedTrackId);
            setSchedule(null);
            setSessions([]);
            setAttendanceData({});
            setStartDate('');
            setSelectedDays([1, 3, 5]);
            addToast('Schedule deleted', 'success');
        } catch (err) {
            addToast('Failed to delete schedule', 'error');
        }
    };

    const handleOpenAttendance = async (courseId, sessionIndex, sessionDate) => {
        const course = trackCourses.find(c => String(c.id) === String(courseId));
        if (!course) return;

        setOpeningSession(`${courseId}-${sessionIndex}`);
        try {
            const plainCode = generateAttendanceCode();
            const { hash, salt } = await hashAttendanceCode(plainCode);

            const now = new Date();
            const endsAt = new Date(now.getTime() + 15 * 60 * 1000);

            const session = await supabaseService.openCourseAttendance({
                courseId: String(courseId),
                courseTitle: course.title,
                durationMinutes: 15,
                openedBy: user?.id,
                codeHash: hash,
                codeSalt: salt,
                plainCode,
            });

            addToast(`Attendance opened for "${course.title}" — Code: ${plainCode}`, 'success');
            await loadSchedule();
        } catch (err) {
            console.error('Failed to open attendance:', err);
            addToast('Failed to open attendance', 'error');
        } finally {
            setOpeningSession(null);
        }
    };

    const toggleDay = (day) => {
        setSelectedDays(prev =>
            prev.includes(day) ? prev.filter(d => d !== day) : [...prev, day].sort()
        );
    };

    const previewSessions = () => {
        if (!startDate || selectedDays.length === 0) return [];
        return supabaseService.generateTrackSessionDates({
            start_date: startDate,
            session_days: selectedDays,
            weeks: 6,
        });
    };

    const preview = (!schedule && startDate && selectedDays.length > 0) ? previewSessions() : sessions;

    if (!selectedTrackId) {
        return (
            <div className="space-y-6">
                <div>
                    <h2 className="text-xl font-bold flex items-center gap-2">
                        <Icon name="Calendar" size={24} className="text-secondary" />
                        Track Course Schedule
                    </h2>
                    <p className="text-sm text-muted-foreground mt-1">
                        Set a 6-week schedule for each track. Each course meets 3 times per week.
                        Admin opens attendance for individual sessions.
                    </p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {tracks.filter(t => t.courses?.length > 0).map(track => (
                        <button
                            key={track.id}
                            onClick={() => setSelectedTrackId(track.id)}
                            className="bg-card border border-border rounded-2xl p-5 text-left hover:border-secondary/50 hover:shadow-lg transition-all group"
                        >
                            <div className="flex items-center gap-3 mb-2">
                                <div className="w-10 h-10 rounded-xl bg-secondary/10 flex items-center justify-center">
                                    <Icon name="Layers" size={18} className="text-secondary" />
                                </div>
                                <div>
                                    <h3 className="font-bold text-sm group-hover:text-secondary transition-colors">{track.title}</h3>
                                    <p className="text-xs text-muted-foreground">{track.courses.length} course{track.courses.length !== 1 ? 's' : ''}</p>
                                </div>
                            </div>
                        </button>
                    ))}
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <button onClick={() => { setSelectedTrackId(null); setSchedule(null); setSessions([]); }} className="text-xs font-bold text-muted-foreground hover:text-primary mb-2 flex items-center gap-1">
                        <Icon name="ArrowLeft" size={12} /> All Tracks
                    </button>
                    <h2 className="text-xl font-bold flex items-center gap-2">
                        <Icon name="Calendar" size={24} className="text-secondary" />
                        {selectedTrack?.title} — Schedule
                    </h2>
                    <p className="text-sm text-muted-foreground mt-1">
                        6 weeks × {selectedDays.length} sessions/week = {sessions.length || selectedDays.length * 6} total sessions per course
                    </p>
                </div>
            </div>

            {/* Schedule Configuration */}
            <div className="bg-card border border-border rounded-2xl p-6 space-y-5">
                <h3 className="font-bold text-sm flex items-center gap-2">
                    <Icon name="Settings" size={16} className="text-secondary" />
                    Schedule Configuration
                </h3>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <label className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Start Date</label>
                        <input
                            type="date"
                            value={startDate}
                            onChange={(e) => setStartDate(e.target.value)}
                            className="w-full px-4 py-2.5 bg-background border border-border rounded-xl text-sm"
                        />
                    </div>
                    <div className="space-y-2">
                        <label className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Session Days (3 per week)</label>
                        <div className="flex gap-2">
                            {DAY_OPTIONS.map(day => (
                                <button
                                    key={day}
                                    onClick={() => toggleDay(day)}
                                    className={`flex-1 py-2.5 rounded-xl text-xs font-bold transition-all ${
                                        selectedDays.includes(day)
                                            ? 'bg-secondary text-white'
                                            : 'bg-muted/50 text-muted-foreground hover:bg-muted'
                                    }`}
                                >
                                    {DAY_NAMES[day]}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>

                {/* Session Preview */}
                {preview.length > 0 && (
                    <div className="bg-muted/30 rounded-xl p-4 border border-border">
                        <p className="text-xs font-bold uppercase tracking-wider text-muted-foreground mb-3">
                            Schedule Preview — {preview.length} Sessions
                        </p>
                        <div className="grid grid-cols-3 md:grid-cols-6 gap-2">
                            {preview.map((s, i) => (
                                <div key={i} className="text-center py-2 px-1 bg-background rounded-lg border border-border text-[10px]">
                                    <div className="font-bold text-primary">W{s.week}</div>
                                    <div className="text-muted-foreground">{DAY_NAMES[s.dayOfWeek]}</div>
                                    <div className="text-muted-foreground">{s.date.slice(5)}</div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                <div className="flex gap-3">
                    <Button onClick={handleSaveSchedule} disabled={saving || !startDate || selectedDays.length === 0}>
                        {saving ? 'Saving...' : schedule ? 'Update Schedule' : 'Save Schedule'}
                    </Button>
                    {schedule && (
                        <Button variant="outline" onClick={handleDeleteSchedule} className="text-red-500 border-red-500/20 hover:bg-red-500/10">
                            Delete Schedule
                        </Button>
                    )}
                </div>
            </div>

            {/* Course Sessions Grid */}
            {schedule && sessions.length > 0 && (
                <div className="space-y-4">
                    <h3 className="font-bold text-sm flex items-center gap-2">
                        <Icon name="BookOpen" size={16} className="text-secondary" />
                        Course Sessions ({trackCourses.length} courses × {sessions.length} sessions)
                    </h3>

                    {trackCourses.map(course => {
                        const isExpanded = expandedCourse === course.id;
                        const courseSessions = attendanceData[String(course.id)] || [];
                        const openedCount = courseSessions.length;

                        return (
                            <div key={course.id} className="bg-card border border-border rounded-2xl overflow-hidden">
                                <button
                                    onClick={() => setExpandedCourse(isExpanded ? null : course.id)}
                                    className="w-full flex items-center justify-between p-5 text-left hover:bg-muted/30 transition-colors"
                                >
                                    <div className="flex items-center gap-4">
                                        <div className="w-10 h-10 rounded-xl bg-secondary/10 flex items-center justify-center">
                                            <Icon name="BookOpen" size={18} className="text-secondary" />
                                        </div>
                                        <div>
                                            <h4 className="font-bold text-sm">{course.title}</h4>
                                            <p className="text-xs text-muted-foreground">
                                                {openedCount}/{sessions.length} sessions opened
                                                {openedCount > 0 && (
                                                    <span className="ml-2 text-emerald-500 font-bold">
                                                        {Math.round((openedCount / sessions.length) * 100)}%
                                                    </span>
                                                )}
                                            </p>
                                        </div>
                                    </div>
                                    <Icon name={isExpanded ? "ChevronUp" : "ChevronDown"} size={18} className="text-muted-foreground" />
                                </button>

                                {isExpanded && (
                                    <div className="border-t border-border p-5">
                                        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3">
                                            {sessions.map((session, idx) => {
                                                const isOpening = openingSession === `${course.id}-${idx}`;
                                                const matchingSession = courseSessions.find(s => {
                                                    try {
                                                        const meta = JSON.parse(s.description || '{}');
                                                        const sessionDate = meta.sessionDate || s.start_time?.split('T')[0];
                                                        return sessionDate === session.date;
                                                    } catch { return false; }
                                                });
                                                const isOpen = matchingSession?.status === 'live';
                                                const isCompleted = matchingSession?.status === 'completed';

                                                return (
                                                    <div
                                                        key={idx}
                                                        className={`rounded-xl p-3 border text-center transition-all ${
                                                            isOpen ? 'bg-red-50 border-red-200 dark:bg-red-500/10 dark:border-red-500/20' :
                                                            isCompleted ? 'bg-emerald-50 border-emerald-200 dark:bg-emerald-500/10 dark:border-emerald-500/20' :
                                                            'bg-background border-border hover:border-secondary/50'
                                                        }`}
                                                    >
                                                        <div className="text-[10px] font-bold text-muted-foreground mb-1">W{session.week} — S{idx + 1}</div>
                                                        <div className="text-xs font-bold text-primary mb-0.5">{DAY_NAMES[session.dayOfWeek]}</div>
                                                        <div className="text-[10px] text-muted-foreground mb-2">{session.date.slice(5)}</div>

                                                        {isCompleted ? (
                                                            <span className="inline-flex items-center gap-1 text-[9px] font-black uppercase text-emerald-500">
                                                                <Icon name="CheckCircle2" size={10} /> Done
                                                            </span>
                                                        ) : isOpen ? (
                                                            <span className="inline-flex items-center gap-1 text-[9px] font-black uppercase text-red-500 animate-pulse">
                                                                <Icon name="Radio" size={10} /> Live
                                                            </span>
                                                        ) : (
                                                            <Button
                                                                size="sm"
                                                                onClick={() => handleOpenAttendance(course.id, idx, session.date)}
                                                                disabled={isOpening}
                                                                className="w-full text-[10px] py-1 px-2"
                                                            >
                                                                {isOpening ? '...' : 'Open'}
                                                            </Button>
                                                        )}
                                                    </div>
                                                );
                                            })}
                                        </div>
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            )}
        </div>
    );
};

export default TrackCourseSchedule;