import React from 'react';
import Icon from '../../../components/AppIcon';

const StatsCard = ({ title, value, change, changeType, icon, iconBg }) => {
  const isPositive = changeType === 'positive';
  const isNeutral = changeType === 'neutral';

  return (
    <div className="bg-card rounded-2xl p-6 shadow-[0_4px_12px_rgba(27,54,93,0.08)] transition-all duration-300 hover:shadow-[0_8px_24px_rgba(27,54,93,0.12)]">
      <div className="flex items-start justify-between mb-4">
        <div className={`w-12 h-12 rounded-xl flex items-center justify-center ${iconBg}`}>
          <Icon name={icon} size={24} color="#FFFFFF" />
        </div>
        {change && (
          <div className={`flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium ${
            isPositive ? 'bg-success/10 text-success' : isNeutral ?'bg-muted text-muted-foreground': 'bg-error/10 text-error'
          }`}>
            <Icon 
              name={isPositive ? 'TrendingUp' : isNeutral ? 'Minus' : 'TrendingDown'} 
              size={14} 
            />
            <span>{change}</span>
          </div>
        )}
      </div>
      <h3 className="text-2xl md:text-3xl lg:text-4xl font-bold text-foreground mb-1">{value}</h3>
      <p className="text-sm text-muted-foreground">{title}</p>
    </div>
  );
};

export default StatsCard;